// ============================================
// BRIGHTPATH CONSULTING
// DAILY LEAD SUMMARY
// FILTER LAST 24 HOURS
// ============================================

// Current time
const now = new Date();

// 24 hours before now
const twentyFourHoursAgo = new Date(
  now.getTime() - (24 * 60 * 60 * 1000)
);

// Get all rows from Google Sheets
const rows = $input.all();

// ============================================
// 1. FILTER LEADS FROM LAST 24 HOURS
// ============================================

const recentLeads = rows.filter(item => {

  const data = item.json;

  // Support both possible header formats
  const submittedAt =
    data['Submitted At'] ||
    data['SubmittedAt'];

  // If there is no submission date, ignore the row
  if (!submittedAt) {
    return false;
  }

  const submittedDate = new Date(submittedAt);

  // Keep only valid dates within the last 24 hours
  return (
    !isNaN(submittedDate.getTime()) &&
    submittedDate >= twentyFourHoursAgo &&
    submittedDate <= now
  );
});

// ============================================
// 2. SEPARATE LEADS BY CATEGORY
// ============================================

const hotLeads = recentLeads.filter(item => {
  const category =
    item.json['Category'] ||
    item.json['category'];

  return String(category || '').trim().toLowerCase() === 'hot';
});

const warmLeads = recentLeads.filter(item => {
  const category =
    item.json['Category'] ||
    item.json['category'];

  return String(category || '').trim().toLowerCase() === 'warm';
});

const coldLeads = recentLeads.filter(item => {
  const category =
    item.json['Category'] ||
    item.json['category'];

  return String(category || '').trim().toLowerCase() === 'cold';
});

// ============================================
// 3. FUNCTION TO CLEAN LEAD DATA
// ============================================

function formatLead(item) {

  const data = item.json;

  return {
    lead_id:
      data['Lead ID'] ||
      data['LeadID'] ||
      data['lead_id'] ||
      '',

    name:
      data['Name'] ||
      data['name'] ||
      '',

    email:
      data['Email'] ||
      data['email'] ||
      '',

    company:
      data['Company'] ||
      data['company'] ||
      '',

    budget:
      data['Budget'] ||
      data['budget'] ||
      '',

    urgency:
      data['Urgency'] ||
      data['urgency'] ||
      '',

    service:
  data['Service Interest'] ||
  '',

    score:
      data['Score'] ||
      data['score'] ||
      ''
  };
}

// ============================================
// 4. RETURN DAILY SUMMARY DATA
// ============================================

return [
  {
    json: {

      summary_date: now.toISOString(),

      total_leads: recentLeads.length,

      hot_count: hotLeads.length,

      warm_count: warmLeads.length,

      cold_count: coldLeads.length,

      hot_leads: hotLeads.map(formatLead),

      warm_leads: warmLeads.map(formatLead),

      cold_leads: coldLeads.map(formatLead)

    }
  }
];

const data = $json;

// ============================================
// BRIGHTPATH CONSULTING
// DAILY LEAD SUMMARY
// BUILD EMAIL CONTENT
// ============================================

function formatLeads(leads) {
  if (!leads || leads.length === 0) {
    return 'None';
  }

  return leads.map((lead, index) => {
    return `${index + 1}. ${lead.name} - ${lead.company}
   Email: ${lead.email}
   Service: ${lead.service}
   Budget: ${lead.budget}
   Urgency: ${lead.urgency}
   Score: ${lead.score}`;
  }).join('\n\n');
}

const summary = `Brightpath Consulting — Daily Lead Summary

Leads received in the last 24 hours: ${data.total_leads}

HOT LEADS (${data.hot_count})
${formatLeads(data.hot_leads)}

WARM LEADS (${data.warm_count})
${formatLeads(data.warm_leads)}

COLD LEADS (${data.cold_count})
${formatLeads(data.cold_leads)}
`;

return {
  json: {
    ...data,
    summary_text: summary
  }
};
